package com.keysbook.app

import android.app.Activity
import android.content.Intent
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.BaseAdapter
import android.widget.Button
import android.widget.ListView
import android.widget.TextView
import android.widget.Toast
import java.util.concurrent.Executors

/**
 * Model browser: fetches the models a key can actually reach, and tests any
 * model on tap. Network work runs off the UI thread.
 */
class ModelsActivity : Activity() {

    private lateinit var vault: Vault
    private lateinit var entry: Vault.Entry
    private lateinit var title: TextView
    private lateinit var status: TextView
    private lateinit var list: ListView
    private lateinit var adapter: ModelAdapter

    private val io = Executors.newSingleThreadExecutor()
    private val ui = Handler(Looper.getMainLooper())
    private val models = mutableListOf<String>()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_models)

        vault = AppState.get(this)
        val id = intent.getStringExtra(EXTRA_ID)
        val found = id?.let { vault.find(it) }
        if (!vault.unlocked || found == null) {
            startActivity(Intent(this, MainActivity::class.java))
            finish()
            return
        }
        entry = found

        title = findViewById(R.id.title)
        status = findViewById(R.id.status)
        list = findViewById(R.id.list)
        adapter = ModelAdapter()
        list.adapter = adapter

        title.text = getString(R.string.models_title, entry.provider)
        findViewById<Button>(R.id.refresh).setOnClickListener { loadModels() }

        list.setOnItemClickListener { _, _, position, _ -> testModel(models[position]) }

        loadModels()
    }

    override fun onDestroy() {
        super.onDestroy()
        io.shutdownNow()
    }

    private fun loadModels() {
        status.text = getString(R.string.loading_models)
        models.clear()
        adapter.notifyDataSetChanged()

        io.execute {
            val result = ModelClient.fetchModels(entry.provider, entry.baseUrl, entry.apiKey)
            ui.post {
                if (isFinishing) return@post
                models.clear()
                models.addAll(result.models)
                adapter.notifyDataSetChanged()

                status.text = when {
                    result.error != null -> result.error
                    models.isEmpty() -> getString(R.string.no_models)
                    else -> getString(R.string.tap_model_hint)
                }
            }
        }
    }

    private fun testModel(model: String) {
        status.text = getString(R.string.testing, model)
        io.execute {
            val result = ModelClient.testModel(entry.provider, entry.baseUrl, entry.apiKey, model)
            ui.post {
                if (isFinishing) return@post
                val msg = if (result.error == null) {
                    getString(R.string.model_ok, model)
                } else {
                    getString(R.string.model_failed, model)
                }
                status.text = msg
                Toast.makeText(this, msg, Toast.LENGTH_SHORT).show()
            }
        }
    }

    private inner class ModelAdapter : BaseAdapter() {
        override fun getCount(): Int = models.size
        override fun getItem(position: Int): Any = models[position]
        override fun getItemId(position: Int): Long = position.toLong()

        override fun getView(position: Int, convertView: View?, parent: ViewGroup?): View {
            val view = convertView ?: LayoutInflater.from(this@ModelsActivity)
                .inflate(R.layout.item_model, parent, false)
            view.findViewById<TextView>(R.id.name).text = models[position]
            return view
        }
    }

    companion object {
        const val EXTRA_ID = "entry_id"
    }
}

package com.keysbook.app

import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedReader
import java.net.HttpURLConnection
import java.net.URL

/**
 * Model-listing client, ported from the Termux app's endpoint probing.
 *
 * The Python app hits the provider's models endpoint and only reports models the
 * key actually returns. Three response shapes are handled:
 *   - OpenAI-compatible : { "data": [ { "id": ... }, ... ] }
 *   - Ollama            : { "models": [ { "name": ... }, ... ] }
 *   - Anthropic         : { "data": [ { "id": ... }, ... ] } with x-api-key auth
 */
object ModelClient {

    data class Result(val models: List<String>, val error: String?)

    private const val TIMEOUT_MS = 20_000

    fun fetchModels(provider: String, baseUrl: String, apiKey: String): Result {
        if (baseUrl.isBlank()) {
            return Result(emptyList(), "This provider needs a custom Base URL.")
        }
        val url = when {
            Providers.isOllama(provider) -> trim(baseUrl) + "/tags"
            Providers.isAnthropic(provider) -> trim(baseUrl) + "/v1/models"
            else -> trim(baseUrl) + "/models"
        }
        return request(url, provider, apiKey)
    }

    /** Probe a single model with a tiny chat call to confirm access. */
    fun testModel(provider: String, baseUrl: String, apiKey: String, model: String): Result {
        if (baseUrl.isBlank()) {
            return Result(emptyList(), "This provider needs a custom Base URL.")
        }
        if (Providers.isOllama(provider)) {
            val url = trim(baseUrl) + "/show"
            return post(url, provider, apiKey, JSONObject().put("model", model),
                listOf("model"))
        }
        val url = trim(baseUrl) + "/chat/completions"
        val body = JSONObject().apply {
            put("model", model)
            put("max_tokens", 1)
            put("messages", JSONArray().put(JSONObject().apply {
                put("role", "user")
                put("content", "ping")
            }))
        }
        return post(url, provider, apiKey, body, listOf("model"))
    }

    private fun request(url: String, provider: String, apiKey: String): Result = try {
        val conn = open(url, provider, apiKey, "GET")
        val code = conn.responseCode
        val text = readBody(conn, code)
        if (code !in 200..299) {
            Result(emptyList(), "HTTP $code: ${short(text)}")
        } else {
            Result(parseModels(text, provider), null)
        }
    } catch (t: Throwable) {
        Result(emptyList(), t.message ?: t.javaClass.simpleName)
    }

    private fun post(
        url: String,
        provider: String,
        apiKey: String,
        body: JSONObject,
        echoKeys: List<String>
    ): Result = try {
        val conn = open(url, provider, apiKey, "POST")
        conn.doOutput = true
        conn.setRequestProperty("Content-Type", "application/json")
        conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
        val code = conn.responseCode
        val text = readBody(conn, code)
        if (code !in 200..299) {
            Result(emptyList(), "HTTP $code: ${short(text)}")
        } else {
            Result(listOf(echoKeys.firstOrNull() ?: "ok"), null)
        }
    } catch (t: Throwable) {
        Result(emptyList(), t.message ?: t.javaClass.simpleName)
    }

    private fun open(url: String, provider: String, apiKey: String, method: String): HttpURLConnection {
        val conn = (URL(url).openConnection() as HttpURLConnection)
        conn.requestMethod = method
        conn.connectTimeout = TIMEOUT_MS
        conn.readTimeout = TIMEOUT_MS
        conn.setRequestProperty("Accept", "application/json")
        if (apiKey.isNotBlank()) {
            if (Providers.isAnthropic(provider)) {
                conn.setRequestProperty("x-api-key", apiKey)
                conn.setRequestProperty("anthropic-version", "2023-06-01")
            } else {
                conn.setRequestProperty("Authorization", "Bearer $apiKey")
            }
        }
        return conn
    }

